changeSet.createProcedure:
CREATE FUNCTION mdm_config_app_upgrade(configId INT, appId INT) RETURNS INT DETERMINISTIC BEGIN -- Deleting existing record for latest version of app for configuration DELETE FROM configurationapplications WHERE configurationId = configId AND applicationId = appId AND applicationVersionId = (SELECT latestVersion FROM applications WHERE applications.id = appId);
-- Change the current record for installed version of application to refer to latest version UPDATE configurationapplications SET applicationVersionId = (SELECT latestVersion FROM applications WHERE applications.id = appId) WHERE configurationId = configId AND applicationId = appId AND action = 1;
-- Upgrade reference to main application if necessary UPDATE configurations SET mainAppId = (SELECT latestVersion FROM applications WHERE applications.id = appId) WHERE id = configId AND mainAppId IS NOT NULL AND EXISTS ( SELECT 1 FROM applicationversions WHERE id = configurations.mainAppId AND applicationId = appId );
-- Upgrade reference to content application if necessary UPDATE configurations SET contentAppId = (SELECT latestVersion FROM applications WHERE applications.id = appId) WHERE id = configId AND contentAppId IS NOT NULL AND EXISTS ( SELECT 1 FROM applicationversions WHERE id = configurations.contentAppId AND applicationId = appId );
RETURN 0; END;

