changeSet.createProcedure:
CREATE FUNCTION mdm_device_permissions_index(device_info TEXT)
RETURNS INT
DETERMINISTIC
BEGIN
    DECLARE permissions JSON;
    DECLARE i INT DEFAULT 0;
    DECLARE count INT DEFAULT 0;
    DECLARE result INT DEFAULT 0;

    IF device_info IS NULL OR LENGTH(TRIM(device_info)) = 0 THEN
        RETURN -1;
    END IF;

    SET permissions = JSON_EXTRACT(device_info, '$.permissions');
    SET count = JSON_LENGTH(permissions);

    WHILE i < count DO
        SET result = result + CAST(JSON_UNQUOTE(JSON_EXTRACT(permissions, CONCAT('$[', i, ']'))) AS SIGNED);
        SET i = i + 1;
    END WHILE;

    RETURN result;
END;

CREATE FUNCTION mdm_resolve_device_property(server_data TEXT, device_data TEXT)
RETURNS TEXT
DETERMINISTIC
BEGIN
    SET server_data = COALESCE(server_data, '');
    SET device_data = COALESCE(device_data, '');

    IF server_data = device_data THEN
        RETURN server_data;
    END IF;

    IF CHAR_LENGTH(device_data) > 0 THEN
        RETURN device_data;
    END IF;

    RETURN server_data;
END;

CREATE FUNCTION mdm_device_launcher_version(launcherAppPkg TEXT, device_info TEXT)
RETURNS TEXT
DETERMINISTIC
BEGIN
    DECLARE deviceApps JSON;
    DECLARE i INT DEFAULT 0;
    DECLARE count INT DEFAULT 0;
    DECLARE app JSON;
    DECLARE pkg TEXT;
    DECLARE version TEXT;

    IF launcherAppPkg IS NULL OR device_info IS NULL THEN
        RETURN NULL;
    END IF;

    SET deviceApps = JSON_EXTRACT(device_info, '$.applications');
    SET count = JSON_LENGTH(deviceApps);

    WHILE i < count DO
        SET app = JSON_EXTRACT(deviceApps, CONCAT('$[', i, ']'));
        SET pkg = JSON_UNQUOTE(JSON_EXTRACT(app, '$.pkg'));
        IF pkg = launcherAppPkg THEN
            SET version = JSON_UNQUOTE(JSON_EXTRACT(app, '$.version'));
            RETURN version;
        END IF;
        SET i = i + 1;
    END WHILE;

    RETURN NULL;
END;

